function remember(fn) {
  const saved = new Map();
  return (n) => {
    if (!saved.has(n)) saved.set(n, fn(n));
    return saved.get(n);
  };
}

let calls = 0;
function paths(n) {
  calls += 1;
  return n <= 2 ? n : paths(n - 1) + paths(n - 2);
}

const fastPaths = remember(paths);
console.log(fastPaths(6));
console.log(calls);
